// KEIS 搶單通知：收 grab.py POST 進來的 payload，組成 LINE 訊息
const body = $input.first().json.body || $input.first().json;
const USER_ID = "Ufab42c56b2eb9b9a9ff18c367b85a6dd"; // 薛力瑜

// 2026-07-26 起統一成三段式回報：
//   新名單   ＝ 公買今天總共進池幾筆（不管符不符合條件）
//   符合條件 ＝ 其中通過篩選、輪得到我們搶的
//   打中     ＝ 真的申請成功的
// 舊版只有「新名單／搶到」兩個數字，掛 0 時分不出是沒出貨還是出了但全不符條件。
// match_today 是後加的欄位；舊 payload 沒帶就退回 new_today（當年那個數字其實就是符合條件數）。
const stats = (b) => {
  const seen = b.new_today || 0;
  const match = (b.match_today != null) ? b.match_today : seen;
  const got = b.grabbed_today || 0;
  return { seen, match, got, line: `新名單 ${seen} ／ 符合條件 ${match} ／ 打中 ${got}` };
};

let text;
if (body.event === 'alert') {
  text = body.text || '⚠ KEIS 搶單警示';
} else if (body.event === 'daily_summary') {
  // 跨日結算保底：每天換日瞬間推一則「前一天」戰果（掛 0 那天也一定有訊息）。
  // 系統是全天分層輪詢、沒有「收工」這回事，措辭別讓人以為要停了。
  const s = stats(body);
  const recovered = body.recovered || 0;
  const d = body.date || '';
  const tail = '🔄 系統持續 24H 監控中';
  const rec = recovered > 0 ? `（含補回 ${recovered} 筆）` : '';
  let hint;
  if (s.got > 0) {
    const missed = s.match - s.got;
    hint = missed > 0 ? `⚠ 有 ${missed} 筆符合條件卻沒搶到（搶輸/配額滿）` : '✅ 符合條件的全打中';
  } else if (s.seen === 0) {
    hint = '✅ 這天公買沒出貨，系統正常運作，只是沒貨可搶';
  } else if (s.match === 0) {
    hint = `ℹ️ 出了 ${s.seen} 筆但沒有一筆符合條件，不是搶輸`;
  } else {
    hint = `⚠ 有 ${s.match} 筆符合條件卻一筆都沒搶到（搶輸/配額滿）`;
  }
  text = `🌙 KEIS 跨日結算（${d} 戰果）\n${s.line}${rec}\n${hint}\n${tail}`;
} else {
  const g = body.grabbed || [];
  const lines = g.map(x => `・${x.name} ${x.phone}｜${x.city} ${x.category} ${x.budget}`).join('\n');
  const left = (body.quota_left != null) ? body.quota_left : '?';
  if (body.new_today != null) {
    // 開盤搶到：帶今日累計，一眼分辨貨少 vs 不符條件 vs 搶輸
    const s = stats(body);
    const missed = s.match - s.got;
    const hint = missed > 0 ? `⚠ 有 ${missed} 筆符合條件還沒搶到（搶輸/配額滿）` : '✅ 符合條件的全打中';
    text = `🎯 KEIS 這批搶到 ${g.length} 筆\n📊 今天累計 ${s.line}｜剩餘配額 ${left}\n${hint}\n\n${lines}`;
  } else {
    // 補漏回查等沒帶今日累計的情況：退回本批數
    text = `🎯 KEIS 搶到 ${g.length} 筆（今日剩餘配額 ${left}）\n\n${lines}`;
  }
}
return [{ json: { userId: USER_ID, text } }];
